package com.chubb.apac.claims.modulith.assessment.service.impl;
import com.chubb.apac.claims.modulith.assessment.dto.request.*;import com.chubb.apac.claims.modulith.assessment.dto.response.*;import com.chubb.apac.claims.modulith.assessment.event.*;import com.chubb.apac.claims.modulith.assessment.mapper.AssessmentMapper;import com.chubb.apac.claims.modulith.assessment.model.*;import com.chubb.apac.claims.modulith.assessment.repository.*;import com.chubb.apac.claims.modulith.assessment.service.*;import com.chubb.apac.claims.modulith.claim.api.*;import com.chubb.apac.claims.modulith.common.dto.PageResponse;import com.chubb.apac.claims.modulith.common.enums.*;import com.chubb.apac.claims.modulith.common.exception.*;import java.time.Instant;import java.util.*;import org.springframework.context.ApplicationEventPublisher;import org.springframework.data.domain.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service @Transactional
public class AssessmentServiceImpl implements AssessmentService{
 private final AssessmentRepository assessments;private final AssessmentStatusHistoryRepository history;private final DecisionRecordRepository decisions;private final ValidationRuleRepository rules;private final ClaimWorkflowApi claims;private final AssessmentMapper mapper;private final AssessmentIdGenerator ids;private final ApplicationEventPublisher events;
 public AssessmentServiceImpl(AssessmentRepository a,AssessmentStatusHistoryRepository h,DecisionRecordRepository d,ValidationRuleRepository r,ClaimWorkflowApi c,AssessmentMapper m,AssessmentIdGenerator i,ApplicationEventPublisher e){assessments=a;history=h;decisions=d;rules=r;claims=c;mapper=m;ids=i;events=e;}
 public AssessmentResponse submit(String claimId,String assessor,Set<Market> markets,String correlationId,SubmitAssessmentRequest r){ClaimAccessView claim=claims.requireAssignedStaffClaim(claimId,assessor,markets);Assessment a=assessments.findByClaimId(claimId).orElseGet(()->{Assessment draft=new Assessment();draft.setAssessmentId(ids.nextAssessmentId());draft.setClaimId(claimId);draft.setAssessorId(assessor);draft.setMarket(claim.market());draft.setProductType(claim.productType());draft.setCreatedBy(assessor);return draft;});if(a.getStatus()!=null&&a.getStatus()!=AssessmentStatus.IN_PROGRESS)throw new ConflictException("Assessment has already been submitted");if(!a.getAssessorId().equals(assessor))throw new ForbiddenException("Assessment is owned by another assessor");apply(a,r.findings(),r.recommendedDecision(),r.recommendationReason(),r.estimatedLiability(),r.riskFactors());a.setStatus(AssessmentStatus.SUBMITTED);a.setSubmittedAt(Instant.now());a.setUpdatedBy(assessor);assessments.saveAndFlush(a);status(a,null,AssessmentStatus.SUBMITTED,"Assessment submitted",assessor);claims.transition(claimId,markets,ClaimStatus.UNDER_REVIEW,ClaimStatus.READY_FOR_DECISION,"Assessment submitted",assessor,correlationId);events.publishEvent(new AssessmentSubmittedEvent(UUID.randomUUID().toString(),a.getAssessmentId(),claimId,assessor,a.getSubmittedAt(),correlation(correlationId)));return mapper.toResponse(a);}
 @Transactional(readOnly=true) public AssessmentResponse get(String claimId,String staff,Set<Market> markets){claims.requireAssignedStaffClaim(claimId,staff,markets);return mapper.toResponse(find(claimId));}
 public AssessmentResponse update(String claimId,String staff,Set<Market> markets,UpdateAssessmentRequest r){ClaimAccessView c=claims.requireAssignedStaffClaim(claimId,staff,markets);Assessment a=assessments.findByClaimId(claimId).orElseGet(()->{if(r.findings()==null||r.recommendedDecision()==null||r.recommendationReason()==null)throw new BusinessValidationException("A new draft requires findings, recommendedDecision and recommendationReason");Assessment draft=new Assessment();draft.setAssessmentId(ids.nextAssessmentId());draft.setClaimId(claimId);draft.setAssessorId(staff);draft.setMarket(c.market());draft.setProductType(c.productType());draft.setStatus(AssessmentStatus.IN_PROGRESS);draft.setCreatedBy(staff);return draft;});if(a.getStatus()!=AssessmentStatus.IN_PROGRESS)throw new ConflictException("Only an in-progress assessment can be updated");if(!a.getAssessorId().equals(staff))throw new ForbiddenException("Assessment is owned by another assessor");apply(a,r.findings()==null?a.getFindings():r.findings(),r.recommendedDecision()==null?a.getRecommendedDecision():r.recommendedDecision(),r.recommendationReason()==null?a.getRecommendationReason():r.recommendationReason(),r.estimatedLiability()==null?a.getEstimatedLiability():r.estimatedLiability(),r.riskFactors()==null?a.getRiskFactors():r.riskFactors());a.setUpdatedBy(staff);assessments.save(a);return mapper.toResponse(a);}
 @Transactional(readOnly=true) public AssessmentValidationResponse validate(String claimId,String staff,Set<Market> markets,String correlationId){ClaimAccessView c=claims.requireAssignedStaffClaim(claimId,staff,markets);Assessment a=find(claimId);List<ValidationErrorResponse> errors=new ArrayList<>();if(a.getFindings()==null||a.getFindings().isBlank())errors.add(new ValidationErrorResponse("FINDINGS_REQUIRED","Findings are required",ValidationSeverity.ERROR));if(a.getRecommendationReason()==null||a.getRecommendationReason().isBlank())errors.add(new ValidationErrorResponse("REASON_REQUIRED","Recommendation reason is required",ValidationSeverity.ERROR));for(ValidationRule rule:rules.findByMarketAndProductTypeAndActiveTrue(c.market(),c.productType())){errors.add(new ValidationErrorResponse(rule.getRuleKey(),rule.getRuleText(),rule.getSeverity()));}boolean valid=errors.stream().noneMatch(x->x.severity()==ValidationSeverity.ERROR);if(!valid)events.publishEvent(new ValidationFailedEvent(UUID.randomUUID().toString(),a.getAssessmentId(),claimId,errors.stream().map(ValidationErrorResponse::code).toList(),Instant.now(),correlation(correlationId)));return new AssessmentValidationResponse(valid,List.copyOf(errors));}
 @Transactional(readOnly=true) public PageResponse<PendingAssessmentResponse> pending(Set<Market> markets,Pageable p){if(markets==null||markets.isEmpty())throw new ForbiddenException("No market access is assigned");return PageResponse.from(assessments.findByStatusAndMarketIn(AssessmentStatus.SUBMITTED,markets,p).map(mapper::toPending));}
 public DecisionResponse approve(String id,String manager,Set<Market> markets,String correlationId,DecisionRequest r){return decide(id,manager,markets,correlationId,r.reason(),Decision.APPROVED,AssessmentStatus.APPROVED_BY_MANAGER,ClaimStatus.APPROVED);}
 public DecisionResponse reject(String id,String manager,Set<Market> markets,String correlationId,DecisionRequest r){return decide(id,manager,markets,correlationId,r.reason(),Decision.REJECTED,AssessmentStatus.REJECTED_BY_MANAGER,ClaimStatus.REJECTED);}
 @Transactional(readOnly=true) public DecisionResponse decision(String id,Set<Market> markets){ClaimAccessView c=claims.requireManagerClaim(id,markets);return mapper.toResponse(decisions.findByClaimId(id).orElseThrow(()->new ResourceNotFoundException("Decision not found")),c.status());}
 private DecisionResponse decide(String id,String manager,Set<Market> markets,String correlationId,String reason,Decision decision,AssessmentStatus next,ClaimStatus claimNext){ClaimAccessView c=claims.requireManagerClaim(id,markets);if(decisions.existsByClaimId(id))throw new ConflictException("A decision already exists for this claim");Assessment a=find(id);if(a.getStatus()!=AssessmentStatus.SUBMITTED)throw new ConflictException("Assessment is not pending manager review");DecisionRecord d=new DecisionRecord();d.setDecisionId(ids.nextDecisionId());d.setClaimId(id);d.setDecision(decision);d.setReason(reason.trim());d.setDeciderId(manager);d.setDecisionDate(Instant.now());d.setCreatedBy(manager);d.setUpdatedBy(manager);decisions.saveAndFlush(d);AssessmentStatus old=a.getStatus();a.setStatus(next);a.setUpdatedBy(manager);status(a,old,next,"Manager decision: "+decision,manager);claims.transition(id,markets,ClaimStatus.READY_FOR_DECISION,claimNext,reason,manager,correlationId);events.publishEvent(new DecisionMadeEvent(UUID.randomUUID().toString(),id,decision,reason,manager,d.getDecisionDate(),decision==Decision.APPROVED?a.getEstimatedLiability():null,c.market(),c.productType(),correlation(correlationId)));return mapper.toResponse(d,claimNext);}
 private Assessment find(String id){return assessments.findByClaimId(id).orElseThrow(()->new ResourceNotFoundException("Assessment not found"));}private void apply(Assessment a,String findings,RecommendedDecision recommended,String reason,java.math.BigDecimal liability,List<String> risks){a.setFindings(findings.trim());a.setRecommendedDecision(recommended);a.setRecommendationReason(reason.trim());a.setEstimatedLiability(liability);a.setRiskFactors(risks.stream().map(String::trim).filter(x->!x.isBlank()).distinct().toList());}private void status(Assessment a,AssessmentStatus old,AssessmentStatus next,String reason,String actor){AssessmentStatusHistory h=new AssessmentStatusHistory();h.setAssessmentId(a.getAssessmentId());h.setOldStatus(old);h.setNewStatus(next);h.setReason(reason);h.setChangedBy(actor);h.setChangedAt(Instant.now());h.setCreatedBy(actor);h.setUpdatedBy(actor);history.save(h);}private String correlation(String v){return v==null||v.isBlank()?UUID.randomUUID().toString():v;}
}
